add_action( 'woocommerce_remove_cart_item', 'perfectpixel_remove_paired_cart_item', 10, 2 );

function perfectpixel_remove_paired_cart_item( $removed_key, $cart ) {
	static $running = false;
	if ( $running ) {
		return; // Our own removal triggers this hook again.
	}

	// Pairs of product IDs that must stay together.
	$pairs = array(
		array( 101, 202 ),
	);

	$removed = $cart->get_cart_item( $removed_key );
	if ( ! $removed ) {
		return;
	}
	$removed_id = (int) $removed['product_id'];

	$partners = array();
	foreach ( $pairs as $pair ) {
		if ( in_array( $removed_id, $pair, true ) ) {
			$partners = array_merge( $partners, array_diff( $pair, array( $removed_id ) ) );
		}
	}
	if ( ! $partners ) {
		return;
	}

	$running = true;
	foreach ( $cart->get_cart() as $key => $item ) {
		if ( $key !== $removed_key && in_array( (int) $item['product_id'], $partners, true ) ) {
			$cart->remove_cart_item( $key );
		}
	}
	$running = false;
}
